function beginDarkTunnelPortal(){if(isDarkTunnel()||V71.tunnel.transition)return false;V71.tunnel.transition='into';state='portal';portalTime=0;portalFrom=1;portalSwitched=false;clearHeldControls();$('portal-caption').style.display='flex';$('portal-title').textContent='THE BLACKWATER TUNNEL';$('portal-sub').textContent='The bright lagoon narrows into a passage where almost all the light disappears.';return true;}
function beginDarkTunnelExit(){if(!isDarkTunnel()||V71.tunnel.transition)return false;V71.tunnel.transition='out';state='portal';portalTime=0;portalFrom=1;portalSwitched=false;clearHeldControls();$('portal-caption').style.display='flex';$('portal-title').textContent='THE TUNNEL OPENS';$('portal-sub').textContent='Black water gives way to pearl light. The main adventure continues.';return true;}
function updateDarkTunnelPortal(dt){if(!V71.tunnel.transition)return false;portalTime+=dt;if(portalTime>=3.4&&!portalSwitched){if(V71.tunnel.transition==='into')setupDarkTunnelChapter();else{V71.tunnel.active=false;V71.tunnel.complete=true;stage=2;loadStage();}portalSwitched=true;tone(466,.25);tone(698,.3);}if(portalTime>=7){const wasOut=V71.tunnel.transition==='out';V71.tunnel.transition='';state='playing';$('portal-caption').style.display='none';elapsed=0;keys.clear();canvas.focus();hud();if(mode==='sarah')openDialogue(wasOut?currentStage().intro:'tunnel-intro');}return true;}
function tunnelMoveBoss(tx,ty,maxSpeed,accel,dt){const dx=tx-boss.x,dy=ty-boss.y,d=Math.max(1,Math.hypot(dx,dy)),tvx=dx/d*Math.min(maxSpeed,d*1.5),tvy=dy/d*Math.min(maxSpeed*.78,d*1.25);boss.vx+=clamp(tvx-boss.vx,-accel*dt,accel*dt);boss.vy+=clamp(tvy-boss.vy,-accel*dt,accel*dt);boss.x+=boss.vx*dt;boss.y+=boss.vy*dt;boss.x=clamp(boss.x,BLACKWATER_ARENA_START+280,W-360);boss.y=clamp(boss.y,405,790);boss.facing=boss.vx<0?1:-1;boss.renderAngle+=(clamp(Math.atan2(boss.vy,Math.max(120,Math.abs(boss.vx))),-.3,.3)-boss.renderAngle)*(1-Math.exp(-dt*5));}
function tunnelBossState(next){boss.sharkState=next;boss.sharkTime=0;boss.biteLatch=false;if(next==='lock'){boss.aimX=nessie.x;boss.aimY=nessie.y;}boss.vulnerable=next==='recover';if(next==='recover')boss.recoil=.6;}
function tunnelShot(){if(projectiles.length>38)return;const a=Math.atan2(nessie.y-boss.y,nessie.x-boss.x);for(const off of [-.26,0,.26])projectiles.push({x:boss.x,y:boss.y,vx:Math.cos(a+off)*235,vy:Math.sin(a+off)*235,life:4,age:0,type:'pearl',variant:'straight',tunnelOwned:true,hitRadius:34});}
function updateTunnelProjectiles(dt){for(const p of projectiles){if(!p.tunnelOwned)continue;p.age+=dt;p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(Math.hypot(p.x-nessie.x,p.y-nessie.y)<(p.hitRadius||34)){p.life=0;if(dashTime>0){score+=15;tone(500,.05,.018);}else hurt(p.x);}}projectiles=projectiles.filter(p=>!p.tunnelOwned||(p.life>0&&p.x>0&&p.x<W&&p.y>waterSurface()+5&&p.y<930));}
function updateGiantShark(dt){
 if(!boss)return;if(boss.hp<=0){if(!V71.tunnel.victoryReady){V71.tunnel.victoryReady=true;boss.active=false;boss.vulnerable=false;projectiles=[];score+=1400;screenShake=.35;showRewardBanner('perfect','BARON BITE DEFEATED!','THE BLACKWATER PASSAGE IS CLEAR');if(mode==='sarah')openDialogue('tunnel-win');}return;}
 if(!boss.active&&nessie.x>BLACKWATER_ARENA_START+280){boss.active=true;tunnelBossState('prowl');showRewardBanner('perfect','GIANT SHARK!','BARON BITE · GUARDIAN OF THE BLACKWATER');if(mode==='sarah'&&!V71.tunnel.bossIntro){V71.tunnel.bossIntro=true;openDialogue('tunnel-boss');}}if(!boss.active)return;
 boss.clock+=dt;boss.sharkTime+=dt;boss.hitCooldown=Math.max(0,boss.hitCooldown-dt);boss.recoil=Math.max(0,boss.recoil-dt*2.4);boss.eyeBlink=(boss.eyeBlink+dt*.27)%1;
 const wounded=boss.hp<=4,arenaMid=(BLACKWATER_ARENA_START+W)/2,s=boss.sharkState;
 if(s==='prowl'){tunnelMoveBoss(arenaMid+Math.sin(boss.clock*.58)*620,565+Math.sin(boss.clock*.91)*145,wounded?330:285,wounded?720:620,dt);if(boss.sharkTime>(wounded?1.05:1.4))tunnelBossState(boss.hp%2?'lock':'tail');}
 else if(s==='tail'){boss.vx*=Math.exp(-dt*4);boss.vy*=Math.exp(-dt*4);if(boss.sharkTime>.42&&!boss.shot){boss.shot=true;tunnelShot();tone(95,.13,.025);}if(boss.sharkTime>.95){boss.shot=false;tunnelBossState('lock');}}
 else if(s==='lock'){boss.vx*=Math.exp(-dt*5);boss.vy*=Math.exp(-dt*5);if(boss.sharkTime>(wounded?.42:.58))tunnelBossState('charge');}
 else if(s==='charge'){const a=Math.atan2(boss.aimY-boss.y,boss.aimX-boss.x),speed=wounded?930:830;boss.vx=Math.cos(a)*speed;boss.vy=Math.sin(a)*speed;boss.heading=a;boss.facing=boss.vx<0?1:-1;tunnelBossState('lunge');tone(78,.1,.03);}
 else if(s==='lunge'){boss.x+=boss.vx*dt;boss.y+=boss.vy*dt;boss.vx*=Math.exp(-dt*.38);boss.vy*=Math.exp(-dt*.38);boss.x=clamp(boss.x,BLACKWATER_ARENA_START+180,W-250);boss.y=clamp(boss.y,380,820);if(Math.hypot(nessie.x-boss.x,nessie.y-boss.y)<180&&!boss.biteLatch){boss.biteLatch=true;if(dashTime>0){score+=80;rewardPopup(nessie.x,nessie.y-80,'NARROW ESCAPE!','combo','#c8fff1',.7);}else hurt(boss.x);}if(boss.sharkTime>(wounded?.52:.66))tunnelBossState('recover');}
 else if(s==='recover'){tunnelMoveBoss(arenaMid+(boss.facing>0?520:-520),520+Math.sin(boss.clock)*90,150,390,dt);if(Math.hypot(nessie.x-boss.x,nessie.y-boss.y)<205&&dashTime>0&&boss.hitCooldown<=0){boss.hp--;boss.hitCooldown=.8;dashTime=0;invincible=.6;score+=260;bossImpact(boss);rewardPopup(boss.x,boss.y-120,'GIANT HIT! '+boss.hp+'/'+boss.max,'perfect','#fff0af',.9);if(boss.hp<=0){updateGiantShark(0);return;}}if(boss.sharkTime>(wounded?1.15:1.45))tunnelBossState('prowl');}
}
function updateDarkTunnel(dt){if(!isDarkTunnel())return false;invincible=Math.max(0,invincible-dt);if(nessie.x>10350&&!V71.tunnel.checkpointReached){V71.tunnel.checkpointReached=true;checkpoint=10400;health=5;flash('♥ Blackwater checkpoint');if(mode==='sarah')openDialogue('tunnel-checkpoint');}const section=nessie.x<4300?0:nessie.x<8200?1:nessie.x<BLACKWATER_ARENA_START?2:3;if(section!==V71.tunnel.section){V71.tunnel.section=section;const names=['THE LIGHT FADES','THE NARROW PASSAGE','SOMETHING HUGE AHEAD','THE BLACKWATER ARENA'];showRewardBanner('clear',names[section],section===3?'THE TUNNEL OPENS INTO AN ENORMOUS CHAMBER':'BLACKWATER TUNNEL');}updateGiantShark(dt);updateTunnelProjectiles(dt);if(V71.tunnel.victoryReady){V71.tunnel.winTime+=dt;if(V71.tunnel.winTime>1.2&&Math.hypot(nessie.x-(W-190),nessie.y-540)<115)beginDarkTunnelExit();}return true;}
function drawTunnelRock(o,t){const x=o.x-camera;if(x>vw+100||x+o.w<-100)return;ctx.save();ctx.translate(x,o.y);const g=ctx.createLinearGradient(0,0,o.w,o.h);g.addColorStop(0,'#1d2d3b');g.addColorStop(.5,'#101a2a');g.addColorStop(1,'#060a14');ctx.fillStyle=g;ctx.strokeStyle='#34485a';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(0,0,o.w,o.h,34);ctx.fill();ctx.stroke();ctx.strokeStyle='#75c7c833';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(25+i*90,o.h*.45);ctx.lineTo(55+i*78,o.h*.65);ctx.stroke();}ctx.restore();}
function drawDarkTunnelBackdrop(t){if(!isDarkTunnel())return;const line=waterSurface(),arena=clamp((nessie.x-(BLACKWATER_ARENA_START-800))/1300,0,1);ctx.save();const g=ctx.createLinearGradient(0,line,0,H);g.addColorStop(0,arena?'#102735':'#050914');g.addColorStop(.55,arena?'#091b28':'#02050d');g.addColorStop(1,'#01030a');ctx.fillStyle=g;ctx.fillRect(0,line,vw,H-line);ctx.globalAlpha=.18+.16*arena;for(let i=0;i<9;i++){const x=((i*330-camera*.11)%(vw+420)+vw+420)%(vw+420)-210,y=390+(i%4)*135;ctx.strokeStyle=i%2?'#4f8d9f':'#675b8c';ctx.lineWidth=10;ctx.beginPath();ctx.arc(x,y,80+i%3*24,.2,Math.PI*1.7);ctx.stroke();}ctx.globalAlpha=1;ctx.restore();}
function drawTunnelProjectile(p,t){const x=p.x-camera;if(x<-60||x>vw+60||!p.tunnelOwned)return;ctx.save();ctx.translate(x,p.y);ctx.shadowColor='#9ddcff';ctx.shadowBlur=14;ctx.fillStyle='#8bbbd1';ctx.strokeStyle='#ddf9ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,15+Math.sin(t*8+p.age)*2,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}
function drawGiantShark(t){if(!boss||boss.hp<=0)return;drawReefShark(boss,t);}
function drawDarkTunnelWorld(t){if(!isDarkTunnel())return;for(const o of obstacles)drawTunnelRock(o,t);for(let i=0;i<18;i++){const wx=600+i*610,x=wx-camera;if(x<-40||x>vw+40)continue;ctx.fillStyle='#88f1e2';ctx.globalAlpha=.18+.12*Math.sin(t*2+i);ctx.beginPath();ctx.arc(x,850-(i%3)*32,3+i%2,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;for(const p of projectiles)drawTunnelProjectile(p,t);drawGiantShark(t);if(V71.tunnel.victoryReady){drawOrnatePortal(W-190-camera,540,260,t,true);ctx.fillStyle='#dfffff';ctx.font='900 14px Nunito,sans-serif';ctx.textAlign='center';ctx.fillText('PEARL-LIGHT EXIT',W-190-camera,390);}}
function drawDarkTunnelVeil(t){if(!isDarkTunnel())return;const x=nessie.x-camera,y=nessie.y,arena=clamp((nessie.x-(BLACKWATER_ARENA_START-700))/1400,0,1),radius=230+arena*720,edge=.965-arena*.48;ctx.save();const g=ctx.createRadialGradient(x,y,70,x,y,radius);g.addColorStop(0,'rgba(1,4,12,0)');g.addColorStop(.28,'rgba(1,4,12,'+(0.04+arena*.03)+')');g.addColorStop(.72,'rgba(1,4,12,'+(edge*.62)+')');g.addColorStop(1,'rgba(1,4,12,'+edge+')');ctx.fillStyle=g;ctx.fillRect(0,waterSurface(),vw,H-waterSurface());ctx.strokeStyle='rgba(151,244,239,'+(arena?.12:.22)+')';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,115+Math.sin(t*2)*4,0,Math.PI*2);ctx.stroke();ctx.restore();}
function updateDarkTunnelHud(){if(!isDarkTunnel())return false;const active=!!(boss?.active&&boss.hp>0);$('boss-hud').style.display=active?'flex':'none';if(active){$('boss-name').textContent='Baron Bite · Giant Shark';$('boss-health').style.width=boss.hp/boss.max*100+'%';setIconCue($('boss-cue'),boss.vulnerable?'boost':boss.sharkState==='lock'?'warning':'shield',boss.vulnerable?'The giant shark is recovering — attack now':boss.sharkState==='lock'?'Charge locked — move!':'Keep moving and wait for the recovery');$('boss-hud').classList.toggle('vulnerable',boss.vulnerable);}const open=V71.tunnel.victoryReady;setIconCue($('coin-progress'),open?'portal':'compass',open?'The pearl-light exit is open':nessie.x<BLACKWATER_ARENA_START?'Follow Sarah’s light through the tunnel':'Defeat Baron Bite');$('coin-progress').classList.add('quest-text');$('coin-progress-fill').style.width=Math.min(100,nessie.x/W*100)+'%';return true;}
function retryDarkTunnel(){const reached=V71.tunnel.checkpointReached,cp=reached?10400:220;setupDarkTunnelChapter();V71.tunnel.checkpointReached=reached;checkpoint=cp;nessie.x=cp;nessie.y=540;health=5;invincible=2;state='playing';$('overlay').style.display='none';keys.clear();canvas.focus();hud();flash('Back inside the Blackwater Tunnel. Follow the light.');}
function installV71Dialogue(){if(typeof conversations==='undefined')return;Object.assign(conversations,{
'tunnel-intro':{speaker:'Sarah Maria',portrait:'sarah',line:'The lagoon narrows into a tunnel. Behind Sarah, the last bright water disappears until only a little circle of light travels with her.',options:[['Okay… keep swimming.','Tiny bubbles drift through the light, then vanish into the dark ahead.'],['This is MUCH darker than the crab kingdom.','Somewhere far away, something enormous swishes its tail.']],hint:'Visibility is deliberately limited. Stay calm, follow the passage and use the glowing markers as landmarks.'},
'tunnel-checkpoint':{speaker:'Sarah Maria',portrait:'sarah',line:'The walls are getting wider. That usually means either an exit… or an extremely dramatic boss room.',options:[['Please be the exit.','A very large shadow crosses the opening. It is not the exit.'],['Bubble ready.','Good plan. The tunnel is about to get much, much bigger.']],hint:'Checkpoint reached. The arena is close.'},
'tunnel-boss':{speaker:'Baron Bite',portrait:'sarah',line:'The tunnel suddenly opens into a colossal chamber. A gigantic top-hat shark circles once, grins, and blocks the way forward.',options:[['That is an unnecessarily large shark.','Baron Bite appears extremely pleased with this review.'],['Nice hat. Still moving through.','The hat tilts. The shark charges.']],hint:'Baron Bite locks his charge direction before lunging. Dodge the pass, then strike during his recovery. Mermaid Bubble also works during openings.'},
'tunnel-win':{speaker:'Sarah Maria',portrait:'sarah',line:'Baron Bite spins to a stop, his hat somehow still perfectly straight. The black chamber fills with pearl light and a new passage opens.',options:[['Good shark. Very dramatic.','Baron Bite gives one offended bubble and swims away.'],['Back to the adventure.','The dark water brightens with every stroke.']],hint:'The exit is open on the far right. The Pearl Palace is next.'}
});}
